<details><summary>本仓驱动源码（输入，不作为结果证据）</summary>

```ts
import { readFileSync } from 'node:fs';
import { mkdtemp } from 'node:fs/promises';
import { MuxWriter, muxConfiguration } from '/Users/mouriya/Ext/worktrees/issue-196-mux-writer-ff0716f/packages/omp-soroi/src/subagent/main/mux-writer.ts';
const home = await mkdtemp('/tmp/plugin196-local-');
const binary = '/tmp/omp-mux-main-1f7f9ff/omp-rpc-mux';
const tokenFile = '/Users/mouriya/Ext/work/orbstack/pepgent-mux/token';
const bearer = readFileSync(tokenFile, 'utf8').trimEnd();
const server = Bun.spawn([binary,'serve','--listen','127.0.0.1:18464','--token-file',tokenFile], {stdin:'ignore',stdout:'ignore',stderr:'pipe'});
const headers = {Authorization:`Bearer ${bearer}`};
const presence = async () => {const response=await fetch('http://127.0.0.1:18464/agents',{headers}); if(!response.ok) throw new Error(`Presence ${response.status}`); return await response.json();};
let writer: MuxWriter | undefined;
const events: string[] = [];
const controller = new AbortController();
let observing: Promise<void> | undefined;
try {
  let available=false;
  for(let n=0;n<40;n++){try{await presence();available=true;break;}catch{await Bun.sleep(50);}}
  if(!available) throw new Error('Native Mux did not become available');
  const stream = await fetch('http://127.0.0.1:18464/agents/events',{headers,signal:controller.signal});
  if(!stream.ok || !stream.body) throw new Error(`SSE ${stream.status}`);
  observing=(async()=>{try{for await(const chunk of stream.body!) events.push(new TextDecoder().decode(chunk));}catch(error){if(!controller.signal.aborted)throw error;}})();
  const sessionId=Bun.randomUUIDv7();
  const sessionFile=`${home}/worker.jsonl`;
  await Bun.write(sessionFile,JSON.stringify({type:'session',version:3,id:sessionId,timestamp:new Date().toISOString(),cwd:home})+'\n');
  const configuration=muxConfiguration({SOROI_MUX_URL:'ws://127.0.0.1:18464',MUX_AUTH_TOKEN:bearer});
  writer=new MuxWriter('Continuation196',configuration,()=>{throw new Error('Unexpected human IRC');});
  const env:Record<string,string>={};
  for(const [key,value] of Object.entries(process.env)) if(value!==undefined)env[key]=value;
  Object.assign(env,{PATH:`/tmp/omp-mux-main-1f7f9ff:${env.PATH}`,PI_CODING_AGENT_DIR:'/tmp/soroi-185-runtime/agent',SOROI_ROLE:'LocalChild',SOROI_SUBAGENT_PARENT:'Main',MUX_AUTH_TOKEN:bearer});
  const ends:unknown[]=[];
  const launch={argv:['omp','--mode','rpc','--no-extensions','--no-context-files','--session',sessionFile,'--model','opencode-go/deepseek-v4.1-flash','-e','/Users/mouriya/Ext/worktrees/issue-196-mux-writer-ff0716f/packages/omp-soroi'],cwd:home,env,handlers:{onEvent(){},onEnd(end:unknown){ends.push(end);},async onHostToolCall(){throw new Error('Unexpected host tool');},async onHostRead(){throw new Error('Unexpected host URI');}}};
  const first=await writer.start(launch);
  const firstState=await first.generation.command({type:'get_state'});
  const live1=await presence();
  await first.generation.dispose();
  const parked=await presence();
  if(parked.length!==1 || parked[0].generation!==null || writer.isClosed)throw new Error('Park failed to preserve declaration');
  const second=await writer.start(launch);
  const secondState=await second.generation.command({type:'get_state'});
  const live2=await presence();
  if(first.process.generation===second.process.generation || live1[0].since!==live2[0].since)throw new Error('Wake failed continuing writer/new generation invariant');
  if(!firstState || typeof firstState!=='object' || !('sessionId' in firstState) || firstState.sessionId!==sessionId || !secondState || typeof secondState!=='object' || !('sessionId' in secondState) || secondState.sessionId!==sessionId)throw new Error('Wake did not retain native transcript identity');
  await writer.close();
  const after=await presence();
  if(after.length!==0)throw new Error('Writer leaked after shutdown');
  await Bun.sleep(50);
  const result={home,live1,parked,live2,sessionId,firstState,secondState,ends,after,sse:events.join('')};
  await Bun.write(`${home}/evidence.json`,JSON.stringify(result,null,2));
  console.log(JSON.stringify(result,null,2));
}finally{
  await writer?.close();
  controller.abort();
  await observing;
  server.kill('SIGINT');
  await server.exited;
}

